import React, { useState } from 'react';
import { Box, ButtonBase, Button, Typography } from '@mui/material';
import PlayArrowRoundedIcon from '@mui/icons-material/PlayArrowRounded';
import ArrowForwardRoundedIcon from '@mui/icons-material/ArrowForwardRounded';
import { useTranslation } from 'react-i18next';

// "See it in action": the two Alexa setup films on YouTube, in one smart-display
// frame on the films' own night-blue ground. Only a thumbnail loads until the
// visitor presses play, so the page stays fast (PageSpeed, 2026-10-24).
// The dashboard keeps its own copy of these ids in apps/dashboard/lib/setupVideos.ts.
const FILMS = [
    { key: 'athan', id: 'g4oloAI1oDU', href: 'https://alexa.imuslimlife.com/' },
    { key: 'quran', id: '2djOkp4lW1E', href: 'https://alexa.imuslimlife.com/quran-schedule' },
];

const NIGHT = '#0F1B2A';
const GOLD = '#D4AF5F';
const IVORY = '#F3EFE4';

// The films' eight-point star lattice, faded toward the edges.
const LATTICE = `url("data:image/svg+xml,${encodeURIComponent(
    `<svg xmlns='http://www.w3.org/2000/svg' width='96' height='96'><path d='M48 14 L58 38 L82 48 L58 58 L48 82 L38 58 L14 48 L38 38 Z M48 0 V14 M48 82 V96 M0 48 H14 M82 48 H96' fill='none' stroke='${GOLD}' stroke-opacity='.16' stroke-width='1.2'/></svg>`,
)}")`;

export default function SetupVideo() {
    const { t } = useTranslation('alexa');
    const [active, setActive] = useState(0);
    const [playing, setPlaying] = useState(null);
    const film = FILMS[active];
    const k = (s) => t(`films.${film.key}.${s}`);
    const isPlaying = playing === film.id;

    return (
        <Box
            component="section"
            aria-labelledby="films-title"
            sx={{
                position: 'relative', mt: 10, mx: { xs: -2, sm: 0 }, px: { xs: 2.5, sm: 6 }, py: { xs: 6, md: 8 },
                borderRadius: { xs: 0, sm: 6 }, overflow: 'hidden', color: IVORY,
                background: `radial-gradient(80% 90% at 70% 30%, #1d3350 0%, ${NIGHT} 60%, #0a121c 100%)`,
                boxShadow: '0 40px 90px -30px rgba(15,27,42,.65)',
                '&::before': {
                    content: '""', position: 'absolute', inset: 0, backgroundImage: LATTICE,
                    maskImage: 'radial-gradient(70% 70% at 50% 40%, #000 0%, transparent 100%)',
                    WebkitMaskImage: 'radial-gradient(70% 70% at 50% 40%, #000 0%, transparent 100%)',
                    pointerEvents: 'none',
                },
            }}
        >
            <Box sx={{ position: 'relative', maxWidth: 960, mx: 'auto', textAlign: 'center' }}>
                <Typography sx={{ color: GOLD, fontWeight: 600, letterSpacing: '.18em', textTransform: 'uppercase', fontSize: 13, '[dir=rtl] &': { letterSpacing: 0, fontSize: 15 } }}>
                    {t('films.eyebrow')}
                </Typography>
                <Typography id="films-title" variant="h4" component="h3" sx={{ mt: 1.5, fontWeight: 700, color: IVORY }}>
                    {t('films.title')}
                </Typography>

                <Box role="tablist" aria-label={t('films.title')} sx={{ display: { xs: 'grid', sm: 'inline-flex' }, gridTemplateColumns: '1fr 1fr', width: { xs: '100%', sm: 'auto' }, gap: 0.75, mt: 4, p: 0.75, borderRadius: { xs: 4, sm: 99 }, bgcolor: 'rgba(255,255,255,.06)', boxShadow: `inset 0 0 0 1px ${GOLD}33` }}>
                    {FILMS.map((f, i) => (
                        <ButtonBase
                            key={f.key}
                            role="tab"
                            aria-selected={i === active}
                            onClick={() => setActive(i)}
                            sx={{
                                minHeight: 48, px: { xs: 1.5, sm: 2.5 }, py: 0.75, borderRadius: { xs: 3, sm: 99 }, fontSize: { xs: 14, sm: 15 }, lineHeight: 1.3, fontWeight: 600, transition: 'all .25s',
                                color: i === active ? NIGHT : `${IVORY}cc`, bgcolor: i === active ? GOLD : 'transparent',
                                '&:hover': { bgcolor: i === active ? GOLD : 'rgba(255,255,255,.08)' },
                            }}
                        >
                            {t(`films.${f.key}.tab`)}
                        </ButtonBase>
                    ))}
                </Box>

                {/* A smart display: bezel, screen, and a soft shadow for the base. */}
                <Box sx={{ position: 'relative', mt: 5, mx: 'auto', maxWidth: 860 }}>
                    <Box sx={{ p: { xs: 1, sm: 1.75 }, borderRadius: { xs: 3, sm: 5 }, background: 'linear-gradient(150deg, #3a4150, #11151c 45%, #262c36)', boxShadow: `0 30px 60px rgba(0,0,0,.5), inset 0 0 0 1px rgba(255,255,255,.08)` }}>
                        <Box sx={{ position: 'relative', aspectRatio: '16 / 9', borderRadius: { xs: 2, sm: 3.5 }, overflow: 'hidden', bgcolor: '#000' }}>
                            {isPlaying ? (
                                <Box
                                    component="iframe"
                                    src={`https://www.youtube-nocookie.com/embed/${film.id}?autoplay=1&rel=0`}
                                    title={k('tab')}
                                    allow="autoplay; encrypted-media; picture-in-picture; fullscreen"
                                    allowFullScreen
                                    sx={{ position: 'absolute', inset: 0, width: '100%', height: '100%', border: 0 }}
                                />
                            ) : (
                                <ButtonBase onClick={() => setPlaying(film.id)} aria-label={k('play')} sx={{ position: 'absolute', inset: 0, display: 'block', '&:hover .play': { transform: 'scale(1.06)' } }}>
                                    <Box
                                        component="img"
                                        src={`https://i.ytimg.com/vi/${film.id}/maxresdefault.jpg`}
                                        onError={(e) => { e.currentTarget.onerror = null; e.currentTarget.src = `https://i.ytimg.com/vi/${film.id}/hqdefault.jpg`; }}
                                        alt=""
                                        loading="lazy"
                                        sx={{ width: '100%', height: '100%', objectFit: 'cover', display: 'block' }}
                                    />
                                    <Box sx={{ position: 'absolute', inset: 0, background: 'linear-gradient(180deg, transparent 55%, rgba(10,18,28,.75))' }} />
                                    <Box className="play" sx={{ position: 'absolute', insetInlineStart: { xs: 12, sm: 22 }, bottom: { xs: 12, sm: 20 }, transition: 'transform .25s', display: 'flex', alignItems: 'center', gap: 1, paddingInlineStart: '6px', paddingInlineEnd: '16px', py: 0.75, borderRadius: 99, bgcolor: GOLD, color: NIGHT, fontWeight: 700, fontSize: { xs: 14, sm: 16 }, boxShadow: `0 0 0 6px ${GOLD}33, 0 12px 30px rgba(0,0,0,.4)` }}>
                                        <Box component="span" sx={{ width: { xs: 32, sm: 40 }, height: { xs: 32, sm: 40 }, borderRadius: '50%', bgcolor: NIGHT, color: GOLD, display: 'grid', placeItems: 'center' }}>
                                            <PlayArrowRoundedIcon sx={{ fontSize: { xs: 24, sm: 30 } }} />
                                        </Box>
                                        {k('length')}
                                    </Box>
                                </ButtonBase>
                            )}
                        </Box>
                    </Box>
                    <Box sx={{ mx: 'auto', mt: 1.5, width: '42%', height: 14, borderRadius: '50%', background: 'radial-gradient(closest-side, rgba(0,0,0,.55), transparent)' }} />
                </Box>

                <Box component="ul" sx={{ listStyle: 'none', p: 0, m: 0, mt: 4, display: 'flex', flexWrap: 'wrap', justifyContent: 'center', gap: 1.25 }}>
                    {[1, 2, 3].map((n) => (
                        <Box component="li" key={n} sx={{ display: 'flex', alignItems: 'center', gap: 1, px: 2, py: 1, borderRadius: 99, fontSize: 15, bgcolor: 'rgba(255,255,255,.05)', boxShadow: `inset 0 0 0 1px ${GOLD}40` }}>
                            <Box component="span" sx={{ width: 24, height: 24, borderRadius: '50%', bgcolor: `${GOLD}33`, color: GOLD, display: 'grid', placeItems: 'center', fontSize: 13, fontWeight: 700 }}>{n}</Box>
                            {k(`p${n}`)}
                        </Box>
                    ))}
                    {film.key === 'quran' && (
                        <Box component="li" sx={{ display: 'flex', alignItems: 'center', px: 2, py: 1, borderRadius: 99, fontSize: 15, fontWeight: 700, bgcolor: GOLD, color: NIGHT }}>
                            {k('badge')}
                        </Box>
                    )}
                </Box>

                <Typography sx={{ mt: 3, mx: 'auto', maxWidth: 640, color: `${IVORY}bf`, fontSize: 16, lineHeight: 1.6 }}>
                    {k('after')}
                </Typography>

                <Button
                    href={film.href}
                    endIcon={<ArrowForwardRoundedIcon sx={{ '[dir=rtl] &': { transform: 'scaleX(-1)' } }} />}
                    sx={{ mt: 3.5, minHeight: 52, px: 3.5, borderRadius: 99, fontWeight: 700, fontSize: 16, textTransform: 'none', bgcolor: GOLD, color: NIGHT, '&:hover': { bgcolor: '#e2c27a' } }}
                >
                    {k('cta')}
                </Button>
            </Box>
        </Box>
    );
}
